package com.devteciot.dev_erp.Service;
import com.devteciot.dev_erp.DTO.DTOTipoSaida.*; import com.devteciot.dev_erp.Exception.ResourceNotFoundException; import com.devteciot.dev_erp.Models.TipoSaida; import com.devteciot.dev_erp.Repository.TipoSaidaRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class TipoSaidaService { private final TipoSaidaRepository r; public List<TipoSaidaGetDTO> listar(){return r.findByAtivoTrueOrderByNomeAsc().stream().map(this::dto).toList();} public TipoSaidaGetDTO buscar(Long id){return dto(r.findById(id).orElseThrow(()->new ResourceNotFoundException("Tipo de saída não encontrado: "+id)));} public TipoSaidaGetDTO criar(TipoSaidaPostDTO d){if(r.existsByNomeIgnoreCase(d.nome()))throw new IllegalArgumentException("Já existe um tipo de saída com esse nome.");TipoSaida t=new TipoSaida();t.setNome(d.nome().trim());return dto(r.save(t));} public TipoSaidaGetDTO atualizar(Long id,TipoSaidaPostDTO d){TipoSaida t=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Tipo de saída não encontrado: "+id));if(!t.getNome().equalsIgnoreCase(d.nome())&&r.existsByNomeIgnoreCase(d.nome()))throw new IllegalArgumentException("Já existe um tipo de saída com esse nome.");t.setNome(d.nome().trim());return dto(r.save(t));} public void excluir(Long id){TipoSaida t=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Tipo de saída não encontrado: "+id));t.setAtivo(false);r.save(t);} private TipoSaidaGetDTO dto(TipoSaida t){return new TipoSaidaGetDTO(t.getId(),t.getNome(),t.getAtivo(),t.getDataCriacao(),t.getDataUpdate());}}
